/// Returns whether a generated object is handled by the local runtime control plane.
pub(crate) fn generated_is_local_runtime_control_path(target_path: &operit_link::CoreObjectPath) -> bool {
    matches!(target_path.key().as_str(), "linkAccessStore" | "runtimeRemoteLinkService")
}

/// Returns whether one push request targets a schema-declared reverse stream.
fn generated_is_reverse_stream_request(request: &operit_link::CorePushRequest) -> bool {
    matches!((request.targetPath.key().as_str(), request.methodName.as_str()), ("services.archiveTransferManager", "writeArchiveUpload") | ("services.runtimeBrowserService", "submitBrowserInteractions"))
}

